list_tax_zones.code:
final response = await client.taxZones.listTaxZones(queryParams: {'limit': 2});
final taxZones = (response.map as Map)['tax_zones'] as List;
for (final taxZone in taxZones) {
  print('${(taxZone as Map)['id']} ${taxZone['name']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print('${pagination['total']} ${pagination['next_page']}');

